DROP TABLE IF EXISTS `personagens`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `personagens` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nome` varchar(200) NOT NULL,
  `Foto` text NOT NULL,
  `tipo` int NOT NULL,
  `lore` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `personagens_unique` (`nome`),
  KEY `personagens_tipos_FK` (`tipo`),
  KEY `personagens_lore_personagens_FK` (`lore`),
  CONSTRAINT `personagens_lore_personagens_FK` FOREIGN KEY (`lore`) REFERENCES `lore_personagens` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `personagens_tipos_FK` FOREIGN KEY (`tipo`) REFERENCES `tipos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
