INSERT INTO `personagens` VALUES (1,'Solaire of Astora','https://i.pinimg.com/736x/3c/f7/54/3cf7543f578ff9c337e5a621162c7d23.jpg',1,1),(2,'Anastacia of Astora','https://static.wikia.nocookie.net/dark-souls/images/2/24/Anastacia_de_Astora.jpg/revision/latest?cb=20190201160305&path-prefix=es',1,2),(3,'Andre of Astora','https://static.wikia.nocookie.net/darksouls/images/8/8f/DS1R_Andre_of_Astora_%28full_body%2C_smithing%29.webp/revision/latest/scale-to-width-down/250?cb=20230304103242',1,3),(4,'Marvelous Chester','https://darksouls.wiki.fextralife.com/file/Dark-Souls/Marvelous%20Chester.jpg',1,4),(5,'Ciaran','https://i.pinimg.com/736x/04/20/db/0420dba4c9d0a9bea663e804b0e799b9.jpg',1,5),(6,'Crestfallen Warrior','https://darksouls.wiki.fextralife.com/file/Dark-Souls/Crestfall_warrior.jpg',1,6),(7,'Dusk of Oolacile','https://static.wikia.nocookie.net/darksouls/images/0/03/DS1R_Dusk_of_Oolacile_in_Darkroot_Basin_%28half_body%29.webp/revision/latest?cb=20231113213450',1,7),(8,'Eingyi','https://static.wikia.nocookie.net/darksouls/images/1/13/DS1_R_Eingyi_%28full%29.webp/revision/latest?cb=20231110231059',1,8),(9,'Kingseeker Frampt','https://static.wikia.nocookie.net/darksouls/images/1/1e/DS1_Kingseeker_Frampt.png/revision/latest?cb=20121231151526',1,9),(10,'Hawkeye Gough','https://i.pinimg.com/originals/5c/af/7f/5caf7f8abda387a5968b1b77ba1cb8f8.png',1,10),(11,'Griggs of Vinheim','https://static.wikia.nocookie.net/darksouls/images/a/a6/Griggs_of_Vinheim_in_Undead_Burg_%28half_body%29.webp/revision/latest?cb=20240414165840',1,11),(12,'Gwynevere ','https://images.steamusercontent.com/ugc/1809896678258239306/8586C65050C36EFEADA6E461AAE8F1A9C5ED6651/?imw=512&&ima=fit&impolicy=Letterbox&imcolor=%23000000&letterbox=false',1,13),(13,'Ingward','https://images.steamusercontent.com/ugc/785234780857400567/1D01E0D714F15FEDBB0DF7EAAA2EF1537508A9EE/?imw=5000&imh=5000&ima=fit&impolicy=Letterbox&imcolor=%23000000&letterbox=false',1,14),(14,'Darkstalker Kaathe','https://static.wikia.nocookie.